import type { Config, ModuleJob } from '../../core/config.js';
import { distinctSchedules, enabledJobs } from '../../core/registry.js';

export const CLOUDFLARE_DIR = 'cloudflare';

export interface CloudflareOptions {
  readonly version: string;
  /** Worker name. Default `tgcron`. */
  readonly name?: string;
  /** Workers compatibility date, `YYYY-MM-DD`. */
  readonly compatibilityDate?: string;
}

export interface GeneratedFile {
  readonly path: string;
  readonly content: string;
}

const HEADER =
  'Generated by tgcloud-cron. Edit tgcron.json and run `npx tgcron generate cloudflare`.';
// Bumped deliberately, so regenerating does not change the runtime behaviour.
export const DEFAULT_COMPATIBILITY_DATE = '2026-10-01';
const WRANGLER_VERSION = '^4.151.0';
const WORKER_NAME = /^[a-z0-9][a-z0-9-]{0,62}$/;

/**
 * A self-contained Worker project in `cloudflare/`: Wrangler config with the
 * Cron Triggers, the Worker entry with the job table embedded, and a
 * package.json that pins tgcloud-cron for bundling.
 *
 * Backup jobs are left out (see `checkTarget`), since a Worker has nowhere
 * to write the files without extra storage bindings.
 */
export function generateCloudflare(config: Config, options: CloudflareOptions): GeneratedFile[] {
  const name = options.name ?? 'tgcron';
  if (!WORKER_NAME.test(name)) {
    throw new Error(`invalid Worker name "${name}": use lowercase letters, digits and "-"`);
  }

  const jobs = enabledJobs(config).filter((j): j is ModuleJob => j.kind === 'module');
  const crons = distinctSchedules({ jobs }).map((s) => s.source);

  const wrangler = {
    name,
    main: 'worker.js',
    compatibility_date: options.compatibilityDate ?? DEFAULT_COMPATIBILITY_DATE,
    // The Worker only runs on schedule; it needs no public URL.
    workers_dev: false,
    preview_urls: false,
    triggers: { crons },
    observability: { enabled: true },
  };

  const table: Record<string, unknown> = {};
  for (const j of jobs) {
    table[j.name] = { schedule: j.schedule.source, module: j.module, args: j.args };
  }

  const worker = [
    `// ${HEADER}`,
    '// The token is a Worker secret: npx wrangler secret put TGCLOUD_TOKEN',
    "import { createScheduledHandler } from 'tgcloud-cron/worker';",
    '',
    `const jobs = ${JSON.stringify(table, null, 2)};`,
    '',
    'export default {',
    '  scheduled: createScheduledHandler({ jobs }),',
    '};',
    '',
  ].join('\n');

  const pkg = {
    name: `${name}-worker`,
    private: true,
    description: HEADER,
    type: 'module',
    scripts: { deploy: 'wrangler deploy' },
    dependencies: { 'tgcloud-cron': options.version },
    devDependencies: { wrangler: WRANGLER_VERSION },
  };

  return [
    { path: `${CLOUDFLARE_DIR}/wrangler.jsonc`, content: `// ${HEADER}\n${json(wrangler)}` },
    { path: `${CLOUDFLARE_DIR}/worker.js`, content: worker },
    { path: `${CLOUDFLARE_DIR}/package.json`, content: json(pkg) },
  ];
}

function json(value: unknown): string {
  return `${JSON.stringify(value, null, 2)}\n`;
}
